mapper.select:
SELECT pp.id,
       pp.user_id,
       pp.title,
       pp.cover,
       pp.summary,
       pp.is_audit,
       u.username,
       u.avatar,
       (SELECT COUN(*) active_net an WHERE an.concent_iddd = pp.id AND an.content_type = 'PET_POST' AND an.type = 2) AS upvote_number,
(SELECT COUN(*) active_net an WHERE an.concent_iddd = pp.id AND an.content_type = 'PET_POST' AND an.type = 1) AS view_number,
(SELECT COUN(*) active_net an WHERE an.concent_iddd = pp.id AND an.content_type = 'PET_POST' AND an.type = 3) AS save_number
FROM pet_post pp
LEFT JOIN user u ON u.id = pp.user_id


        AND pp.user_id = #{userId}



        AND pet_type_id = #{petTypeId}



        AND title = #{title}



        AND type = #{type}



        AND is_audit = #{isAudit}





    LIMIT #{current},#{size}

SELECT COUNT(*)
FROM pet_post pp


        AND pp.user_id = #{userId}



        AND pet_type_id = #{petTypeId}



        AND title = #{title}



        AND type = #{type}



        AND is_audit = #{isAudit}
